def solve_a_n(N):
    a = [0] * (N + 1)
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        # Need a_{n-1} first
        a_n_minus_1 = a[n-1]

        # Check constraints: a_{n-1} >= 1 since a_n are positive integers
        if a_n_minus_1 > N:
            # This shouldn't happen if we calculate iteratively up to N
            raise ValueError("Index out of bounds for a[a_{n-1}]")

        term1 = a[a_n_minus_1]
        term2 = a[n - a_n_minus_1]

        a[n] = term1 + term2

    return a[1:]

